namespace MyApp.Evals.Tests;

internal sealed class WordCountEvaluator : IEvaluator
{
    public string EvaluatorId => "Words";

    public Task<EvaluationResult> EvaluateAsync(
        IEnumerable<ChatMessage> messages,
        ChatResponse response,
        IEnumerable<EvaluationContext>? additionalContext = null,
        CancellationToken cancellationToken = default)
    {
        var text = response.Text ?? string.Empty;
        var wordCount = text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Length;

        var rating = wordCount switch
        {
            < 5 => EvaluationRating.Poor,
            <= 500 => EvaluationRating.Good,
            _ => EvaluationRating.Average,
        };

        var metric = new NumericMetric(EvaluatorId, wordCount, rating);
        var result = new EvaluationResult(metric);
        return Task.FromResult(result);
    }
}

