using System.Text.Json;

namespace MyApp.Evals.Tests;

public sealed record TelemetryInput(string Agent, string Text);

internal static class InputsLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<TelemetryInput> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "inputs.json");
        return JsonSerializer.Deserialize<List<TelemetryInput>>(
            File.ReadAllText(path), s_options) ?? new();
    }
}

internal static class PriceTable
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    private static Dictionary<string, PriceEntry>? s_prices;

    public static Dictionary<string, PriceEntry> Load()
    {
        if (s_prices is not null) return s_prices;
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "prices.json");
        s_prices = JsonSerializer.Deserialize<Dictionary<string, PriceEntry>>(
            File.ReadAllText(path), s_options) ?? new();
        return s_prices;
    }

    public static decimal Cost(string? modelId, int inputTokens, int outputTokens)
    {
        if (modelId is null || !Load().TryGetValue(modelId, out var entry))
            return 0m;
        return (inputTokens * entry.InputPer1k / 1000m) + (outputTokens * entry.OutputPer1k / 1000m);
    }
}

public sealed record PriceEntry(decimal InputPer1k, decimal OutputPer1k);

internal sealed record TelemetryRecord(
    string AgentName, string Model, int InputTokens,
    int OutputTokens, long LatencyMs, decimal CostUsd);

internal static class TelemetryStore
{
    private static readonly List<TelemetryRecord> s_records = new();

    public static void Record(TelemetryRecord r)
    {
        lock (s_records) s_records.Add(r);
    }

    public static void FlushTo(string outDir)
    {
        Directory.CreateDirectory(outDir);
        List<TelemetryRecord> snapshot;
        lock (s_records) { snapshot = new(s_records); s_records.Clear(); }

        // telemetry.json
        var json = JsonSerializer.Serialize(snapshot, new JsonSerializerOptions { WriteIndented = true });
        File.WriteAllText(Path.Combine(outDir, "telemetry.json"), json);

        // telemetry.md
        var md = new System.Text.StringBuilder();
        md.AppendLine("| Agent | Model | In Tokens | Out Tokens | Latency ms | Cost USD |");
        md.AppendLine("|-------|-------|-----------|------------|------------|----------|");
        foreach (var r in snapshot)
            md.AppendLine($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | {r.CostUsd:F6} |");
        File.WriteAllText(Path.Combine(outDir, "telemetry.md"), md.ToString());

        Console.WriteLine($"[Telemetry] Written to {outDir}");
    }
}

